import { useEffect, useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, ArrowRight, BadgeCheck, Ban, BarChart3, BookOpen, Bot,
  Boxes, Brain, Check, CheckCircle2, ChevronDown, ChevronRight, CircleDollarSign, Clock3,
  Copy, CreditCard, Database, FileCheck2, FileSearch, Filter, Gauge, Hash, HelpCircle,
  History, Home, KeyRound, LayoutDashboard, LockKeyhole, Menu, MoreHorizontal, PanelLeft,
  Play, Plus, RefreshCw, RotateCcw, Search, Server, Settings, Shield, ShieldCheck,
  SlidersHorizontal, Sparkles, Target, TrendingUp, UserRound, Users, X, Zap,
} from 'lucide-react';
import type { ReactNode } from 'react';
import {
  DEMO_SCENARIOS, getAgentActivity, getAllAgents, getAllAuthorizations, getAllEvidence,
  getAllMerchants, getDashboardStats, getRecentTransactions, getRiskTrend, getTransactionById,
  runDemoScenario, seedDatabase, simulateTransaction, createAuthorization, revokeAuthorization,
  updateAgentStatus, verifyEvidence,
} from '@/lib/dataService';
import type { Agent, Authorization, DecisionType, EvidenceRecord, Merchant, TransactionWithRelations } from '@/types';

type Page = 'dashboard' | 'authorizations' | 'agents' | 'simulator' | 'decisions' | 'evidence' | 'policies' | 'settings';

const money = (value: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value);
const compactMoney = (value: number) => value >= 100000 ? `₹${(value / 100000).toFixed(1)}L` : value >= 1000 ? `₹${(value / 1000).toFixed(1)}K` : money(value);
const shortId = (value?: string | null) => value ? `${value.slice(0, 8)}…${value.slice(-4)}` : '—';
const timeAgo = (date?: string) => {
  if (!date) return '—';
  const mins = Math.max(1, Math.round((Date.now() - new Date(date).getTime()) / 60000));
  if (mins < 60) return `${mins}m ago`;
  if (mins < 1440) return `${Math.round(mins / 60)}h ago`;
  return `${Math.round(mins / 1440)}d ago`;
};

function StatusBadge({ status }: { status?: string | null }) {
  const value = (status || 'pending').toLowerCase();
  const label = value === 'executed' ? 'APPROVED' : value.toUpperCase();
  return <span className={`badge-${value === 'approved' || value === 'executed' ? 'approved' : value === 'blocked' ? 'blocked' : value === 'escalated' ? 'escalated' : value === 'failed' ? 'blocked' : 'pending'}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{label}</span>;
}

function RiskPill({ score = 0, level = 'low' }: { score?: number; level?: string }) {
  const tone = level === 'critical' || level === 'high' ? 'text-danger-400 bg-danger-500/10 border-danger-500/20' : level === 'medium' ? 'text-warning-400 bg-warning-500/10 border-warning-500/20' : 'text-success-400 bg-success-500/10 border-success-500/20';
  return <span className={`badge border ${tone}`}><span className="font-mono">{score}</span><span className="text-[10px] uppercase tracking-wide">risk</span></span>;
}

function Logo() {
  return <div className="flex items-center gap-3"><div className="relative flex h-9 w-9 items-center justify-center rounded-xl bg-accent-600 shadow-lg shadow-accent-600/20"><ShieldCheck size={21} className="text-white" /><span className="absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full bg-success-400 ring-2 ring-navy-950" /></div><div><div className="text-[15px] font-bold tracking-tight text-white">Veri<span className="text-accent-400">Flow</span></div><div className="text-[9px] font-medium uppercase tracking-[0.2em] text-navy-500">Payment trust engine</div></div></div>;
}

const navGroups = [
  { label: 'Overview', items: [{ id: 'dashboard' as Page, label: 'Command center', icon: LayoutDashboard }] },
  { label: 'Control plane', items: [
    { id: 'authorizations' as Page, label: 'Authorizations', icon: KeyRound },
    { id: 'agents' as Page, label: 'Agent activity', icon: Bot },
    { id: 'simulator' as Page, label: 'Transaction simulator', icon: Play },
  ] },
  { label: 'Investigation', items: [
    { id: 'decisions' as Page, label: 'Risk decisions', icon: Gauge },
    { id: 'evidence' as Page, label: 'Evidence explorer', icon: FileSearch },
  ] },
  { label: 'Configuration', items: [
    { id: 'policies' as Page, label: 'Policies & controls', icon: SlidersHorizontal },
    { id: 'settings' as Page, label: 'Settings', icon: Settings },
  ] },
];

function Shell({ page, setPage, children, onDemo }: { page: Page; setPage: (page: Page) => void; children: ReactNode; onDemo: () => void }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  return <div className="min-h-screen bg-navy-950 text-navy-100">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[252px] flex-col border-r border-navy-800 bg-navy-950/95 px-4 py-5 backdrop-blur-xl transition-transform duration-300 lg:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="px-2"><Logo /></div>
      <div className="mt-8 flex-1 space-y-7 overflow-y-auto">
        {navGroups.map((group) => <div key={group.label}><div className="mb-2 px-3 text-[10px] font-semibold uppercase tracking-[0.17em] text-navy-600">{group.label}</div>{group.items.map((item) => <button key={item.id} onClick={() => { setPage(item.id); setMobileOpen(false); }} className={page === item.id ? 'nav-link-active mb-1 w-full' : 'nav-link mb-1 w-full'}><item.icon size={17} strokeWidth={1.8} /><span>{item.label}</span>{item.id === 'decisions' && <span className="ml-auto rounded-full bg-warning-500/15 px-1.5 py-0.5 text-[10px] text-warning-400">3</span>}</button>)}</div>)}
      </div>
      <div className="mt-4 rounded-xl border border-accent-500/20 bg-accent-500/5 p-3"><div className="flex items-center gap-2 text-xs font-medium text-accent-300"><span className="h-2 w-2 animate-pulse rounded-full bg-success-400" />Sandbox mode active</div><p className="mt-2 text-[11px] leading-relaxed text-navy-500">No real money is processed. All payment events are simulated.</p></div>
      <div className="mt-4 flex items-center gap-3 border-t border-navy-800 px-2 pt-4"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-accent-600/20 text-xs font-semibold text-accent-300">AM</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-medium text-navy-200">Arjun Mehta</div><div className="text-[10px] text-navy-500">Platform admin</div></div><ChevronDown size={14} className="text-navy-600" /></div>
    </aside>
    {mobileOpen && <button className="fixed inset-0 z-30 bg-black/60 lg:hidden" onClick={() => setMobileOpen(false)} aria-label="Close menu" />}
    <main className="lg:pl-[252px]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-navy-800/80 bg-navy-950/85 px-5 backdrop-blur-xl sm:px-8"><div className="flex items-center gap-3"><button className="btn-ghost p-2 lg:hidden" onClick={() => setMobileOpen(true)} aria-label="Open menu"><Menu size={19} /></button><div className="hidden h-5 w-px bg-navy-800 lg:block" /><div className="text-xs text-navy-500">Trust workspace <span className="mx-2 text-navy-700">/</span><span className="text-navy-300">{navGroups.flatMap(g => g.items).find(i => i.id === page)?.label}</span></div></div><div className="flex items-center gap-2"><button className="btn-secondary hidden sm:inline-flex" onClick={() => setPage('simulator')}><Play size={14} />Simulate transaction</button><button className="btn-primary" onClick={() => runDemo('A')}><Zap size={14} /> <span className="hidden sm:inline">Run agentic demo</span><span className="sm:hidden">Run demo</span></button><button className="btn-secondary hidden md:inline-flex" onClick={() => runDemo('D')}><Shield size={14} />Agent compromise</button></div></header><div className="mx-auto max-w-[1500px] p-5 sm:p-8">{children}</div></main>
  </div>;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 text-[11px] font-semibold uppercase tracking-[0.18em] text-accent-400">{eyebrow && <><span className="h-1.5 w-1.5 rounded-full bg-accent-400" />{eyebrow}</>}</div><h1 className="text-2xl font-semibold tracking-tight text-white sm:text-[28px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-navy-400">{description}</p>}</div>{action}</div>; }
function StatCard({ label, value, hint, icon: Icon, color = 'accent', trend }: { label: string; value: string; hint: string; icon: typeof Activity; color?: string; trend?: string }) { return <div className="card-hover group p-5"><div className="flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl bg-${color}-500/10 text-${color}-400`}><Icon size={19} /></div>{trend && <span className="flex items-center gap-1 text-[11px] font-medium text-success-400"><TrendingUp size={12} />{trend}</span>}</div><div className="mt-4 text-2xl font-semibold tracking-tight text-white">{value}</div><div className="mt-1 text-xs font-medium text-navy-300">{label}</div><div className="mt-2 text-[11px] text-navy-500">{hint}</div></div>; }
function SectionTitle({ title, action }: { title: string; action?: ReactNode }) { return <div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-semibold text-navy-100">{title}</h2>{action}</div>; }
function EmptyState({ icon: Icon, title, text }: { icon: typeof FileSearch; title: string; text: string }) { return <div className="flex min-h-[240px] flex-col items-center justify-center rounded-xl border border-dashed border-navy-700 p-8 text-center"><Icon size={28} className="text-navy-600" /><div className="mt-3 text-sm font-medium text-navy-300">{title}</div><p className="mt-1 max-w-sm text-xs leading-5 text-navy-500">{text}</p></div>; }

function TrendChart({ data }: { data: { date: string; approved: number; blocked: number; escalated: number }[] }) {
  const max = Math.max(1, ...data.map(d => d.approved + d.blocked + d.escalated));
  return <div className="relative h-56 w-full"><div className="absolute inset-0 flex flex-col justify-between text-[10px] text-navy-600"><span>{max}</span><span>{Math.ceil(max / 2)}</span><span>0</span></div><div className="absolute inset-y-0 left-7 right-0 flex flex-col justify-between"><div className="border-t border-navy-800" /><div className="border-t border-navy-800" /><div className="border-t border-navy-800" /></div><div className="absolute inset-y-3 bottom-5 left-10 right-1 flex items-end gap-1 sm:gap-2">{data.map((d, i) => <div key={d.date} className="group flex h-full flex-1 items-end justify-center gap-0.5" title={`${d.date}: ${d.approved} approved, ${d.blocked} blocked, ${d.escalated} escalated`}><div className="w-full rounded-t-sm bg-success-500/70 transition-all group-hover:bg-success-400" style={{ height: `${Math.max(3, d.approved / max * 100)}%` }} /><div className="w-full rounded-t-sm bg-danger-500/70 transition-all group-hover:bg-danger-400" style={{ height: `${d.blocked / max * 100}%` }} /><div className="w-full rounded-t-sm bg-warning-500/70 transition-all group-hover:bg-warning-400" style={{ height: `${d.escalated / max * 100}%` }} />{i % 3 === 0 && <span className="absolute mt-[228px] text-[9px] text-navy-600">{new Date(d.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}</span>}</div>)}</div></div>;
}

function TransactionRow({ tx, onOpen }: { tx: TransactionWithRelations; onOpen: (tx: TransactionWithRelations) => void }) { return <button onClick={() => onOpen(tx)} className="group grid w-full grid-cols-[1.35fr_1fr_1fr_.8fr_.7fr] items-center gap-4 border-b border-navy-800/80 px-5 py-3.5 text-left transition-colors last:border-0 hover:bg-navy-800/40"><div className="min-w-0"><div className="flex items-center gap-2"><span className="font-mono text-xs text-accent-300">{shortId(tx.id)}</span><span className="text-[10px] text-navy-600">{timeAgo(tx.created_at)}</span></div><div className="mt-1 truncate text-xs font-medium text-navy-200">{tx.merchant?.name || 'Unknown merchant'}</div></div><div className="min-w-0"><div className="flex items-center gap-2"><div className="flex h-6 w-6 items-center justify-center rounded-md bg-navy-800 text-accent-300"><Bot size={12} /></div><span className="truncate text-xs text-navy-300">{tx.agent?.name || 'Unknown agent'}</span></div></div><div><span className="text-xs font-medium text-navy-200">{money(Number(tx.amount))}</span><div className="mt-0.5 text-[10px] text-navy-600">{tx.quantity} unit{tx.quantity !== 1 ? 's' : ''} · {tx.currency}</div></div><div><StatusBadge status={tx.status} /></div><div className="flex justify-end text-navy-600 group-hover:text-accent-400"><ChevronRight size={16} /></div></button>; }

function Dashboard({ stats, trend, transactions, onOpen, setPage }: { stats: Awaited<ReturnType<typeof getDashboardStats>> | null; trend: Awaited<ReturnType<typeof getRiskTrend>>; transactions: TransactionWithRelations[]; onOpen: (tx: TransactionWithRelations) => void; setPage: (p: Page) => void }) { return <><PageHeader eyebrow="Overview" title="Command center" description="Monitor every autonomous payment decision before money moves." action={<button className="btn-secondary" onClick={() => setPage('evidence')}><FileCheck2 size={15} />Explore evidence</button>} /><div className="mb-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Agent transactions" value={String(stats?.total ?? 0)} hint="Across all agents" icon={Activity} trend="12.4%" /><StatCard label="Approved & executed" value={String(stats?.approved ?? 0)} hint="Policy-compliant activity" icon={CheckCircle2} color="success" trend="8.2%" /><StatCard label="Blocked" value={String(stats?.blocked ?? 0)} hint="Prevented before execution" icon={Ban} color="danger" /><StatCard label="Risk exposure" value={compactMoney(stats?.riskExposure ?? 0)} hint="Blocked + escalated value" icon={Shield} color="warning" /></div><div className="grid gap-5 xl:grid-cols-[1.5fr_1fr]"><div className="card p-5"><div className="mb-6 flex items-start justify-between"><div><SectionTitle title="Decision activity" /><p className="-mt-2 text-xs text-navy-500">Last 14 days · policy outcomes by day</p></div><div className="flex gap-3 text-[10px] text-navy-400"><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-sm bg-success-400" />Approved</span><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-sm bg-danger-400" />Blocked</span><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-sm bg-warning-400" />Escalated</span></div></div><TrendChart data={trend} /></div><div className="card p-5"><SectionTitle title="Policy health" action={<button className="btn-ghost px-2 py-1 text-xs" onClick={() => setPage('policies')}>View controls <ArrowRight size={12} /></button>} /><div className="mt-5 space-y-5"><div><div className="mb-2 flex justify-between text-xs"><span className="text-navy-300">Authorization coverage</span><span className="font-mono text-success-400">94%</span></div><div className="h-2 overflow-hidden rounded-full bg-navy-800"><div className="h-full w-[94%] rounded-full bg-success-500" /></div></div><div><div className="mb-2 flex justify-between text-xs"><span className="text-navy-300">Evidence integrity</span><span className="font-mono text-accent-400">100%</span></div><div className="h-2 overflow-hidden rounded-full bg-navy-800"><div className="h-full w-full rounded-full bg-accent-500" /></div></div><div><div className="mb-2 flex justify-between text-xs"><span className="text-navy-300">Agent compliance</span><span className="font-mono text-warning-400">87%</span></div><div className="h-2 overflow-hidden rounded-full bg-navy-800"><div className="h-full w-[87%] rounded-full bg-warning-500" /></div></div></div><div className="mt-6 flex items-center gap-3 rounded-lg border border-success-500/15 bg-success-500/5 p-3"><ShieldCheck size={16} className="text-success-400" /><span className="text-xs text-success-300">All evidence chains verified</span></div></div></div><div className="mt-7"><SectionTitle title="Recent transactions" action={<button className="btn-ghost px-2 py-1 text-xs" onClick={() => setPage('decisions')}>View all <ArrowRight size={12} /></button>} /><div className="card overflow-hidden"><div className="hidden grid-cols-[1.35fr_1fr_1fr_.8fr_.7fr] gap-4 border-b border-navy-800 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-navy-600 sm:grid"><span>Transaction</span><span>Agent</span><span>Amount</span><span>Decision</span><span /></div>{transactions.length ? transactions.map(tx => <TransactionRow key={tx.id} tx={tx} onOpen={onOpen} />) : <EmptyState icon={Activity} title="No transactions yet" text="Run the agentic demo to generate a complete decision and evidence trail." />}</div></div></>;
}

function Authorizations({ authorizations, agents, onRefresh }: { authorizations: (Authorization & { agent?: Agent })[]; agents: Agent[]; onRefresh: () => void }) { const [open, setOpen] = useState(false); const [form, setForm] = useState({ max_amount: '70000', agent_id: agents[0]?.id || '', category: 'Electronics', purpose: 'laptop_purchase', quantity: '1', expires: '30' }); const [saving, setSaving] = useState(false); const submit = async () => { setSaving(true); await createAuthorization({ user_id: 'user-001', agent_id: form.agent_id, max_amount: Number(form.max_amount), currency: 'INR', allowed_merchants: [], allowed_categories: [form.category], max_quantity: Number(form.quantity), purpose: form.purpose, expires_at: new Date(Date.now() + Number(form.expires) * 86400000).toISOString() }); setSaving(false); setOpen(false); onRefresh(); }; return <><PageHeader eyebrow="Control plane" title="Authorizations" description="Define the exact boundaries agents must respect before they can propose a payment." action={<button className="btn-primary" onClick={() => setOpen(true)}><Plus size={15} />New authorization</button>} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><div className="card p-4"><div className="text-xs text-navy-500">Active policies</div><div className="mt-2 text-xl font-semibold text-white">{authorizations.filter(a => a.status === 'active').length}</div></div><div className="card p-4"><div className="text-xs text-navy-500">Authorized value</div><div className="mt-2 text-xl font-semibold text-white">{compactMoney(authorizations.reduce((s, a) => s + Number(a.max_amount), 0))}</div></div><div className="card p-4"><div className="text-xs text-navy-500">Expiring in 30 days</div><div className="mt-2 text-xl font-semibold text-warning-400">{authorizations.filter(a => a.status === 'active').length}</div></div></div><div className="card overflow-hidden"><div className="grid grid-cols-[1.4fr_1fr_1fr_1fr_.8fr] gap-4 border-b border-navy-800 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-navy-600"><span>Authorization</span><span>Agent / owner</span><span>Limits</span><span>Scope</span><span>Status</span></div>{authorizations.map(a => <div key={a.id} className="grid grid-cols-[1.4fr_1fr_1fr_1fr_.8fr] items-center gap-4 border-b border-navy-800/70 px-5 py-4 last:border-0"><div><div className="flex items-center gap-2"><KeyRound size={14} className="text-accent-400" /><span className="font-mono text-xs text-navy-300">{shortId(a.id)}</span></div><div className="mt-1 text-xs font-medium text-white">{a.purpose.replaceAll('_', ' ')}</div><div className="mt-1 text-[10px] text-navy-600">Expires {new Date(a.expires_at).toLocaleDateString('en-IN')}</div></div><div className="flex items-center gap-2"><div className="flex h-7 w-7 items-center justify-center rounded-lg bg-navy-800 text-accent-300"><Bot size={13} /></div><span className="text-xs text-navy-300">{a.agent?.name || '—'}</span></div><div><div className="text-xs font-semibold text-white">{money(Number(a.max_amount))}</div><div className="mt-1 text-[10px] text-navy-600">{a.max_quantity} max quantity · {a.currency}</div></div><div><div className="flex flex-wrap gap-1">{a.allowed_categories.length ? a.allowed_categories.map(c => <span key={c} className="badge-pending">{c}</span>) : <span className="text-xs text-navy-500">Any category</span>}</div><div className="mt-1 text-[10px] text-navy-600">{a.allowed_merchants.length ? `${a.allowed_merchants.length} merchants` : 'Any merchant'}</div></div><div className="flex items-center justify-between"><StatusBadge status={a.status} /><button className="btn-ghost p-1.5" onClick={async () => { await revokeAuthorization(a.id); onRefresh(); }} title="Revoke"><MoreHorizontal size={15} /></button></div></div>)}</div>{open && <Modal title="Create authorization" onClose={() => setOpen(false)}><div className="space-y-4"><div><label className="label">Agent</label><select className="input" value={form.agent_id} onChange={e => setForm({ ...form, agent_id: e.target.value })}>{agents.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></div><div className="grid gap-4 sm:grid-cols-2"><div><label className="label">Maximum amount</label><div className="relative"><span className="absolute left-3 top-2 text-sm text-navy-500">₹</span><input className="input pl-7" value={form.max_amount} onChange={e => setForm({ ...form, max_amount: e.target.value })} /></div></div><div><label className="label">Maximum quantity</label><input className="input" type="number" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} /></div></div><div className="grid gap-4 sm:grid-cols-2"><div><label className="label">Allowed category</label><select className="input" value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}><option>Electronics</option><option>Office</option><option>Software</option><option>Books</option><option>Healthcare</option></select></div><div><label className="label">Purpose</label><input className="input" value={form.purpose} onChange={e => setForm({ ...form, purpose: e.target.value })} /></div></div><div><label className="label">Valid for (days)</label><input className="input" type="number" value={form.expires} onChange={e => setForm({ ...form, expires: e.target.value })} /></div><div className="flex justify-end gap-2 pt-2"><button className="btn-secondary" onClick={() => setOpen(false)}>Cancel</button><button className="btn-primary" onClick={submit} disabled={saving}>{saving ? <RefreshCw size={14} className="animate-spin" /> : <Check size={14} />}Create authorization</button></div></div></Modal>}</>; }

function Agents({ activity, onRefresh }: { activity: Awaited<ReturnType<typeof getAgentActivity>>; onRefresh: () => void }) { return <><PageHeader eyebrow="Control plane" title="Agent activity" description="See how each autonomous agent is behaving, spending, and accumulating trust." /><div className="grid gap-5 xl:grid-cols-2">{activity.map(({ agent, total, approved, blocked, escalated, totalValue }) => <div key={agent.id} className="card-hover p-5"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-accent-500/10 text-accent-300"><Bot size={21} /></div><div><div className="font-medium text-white">{agent.name}</div><div className="mt-1 text-xs capitalize text-navy-500">{agent.type} agent · {agent.status}</div></div></div><span className={agent.status === 'active' ? 'badge-approved' : 'badge-blocked'}><span className="h-1.5 w-1.5 rounded-full bg-current" />{agent.status}</span></div><div className="mt-6 grid grid-cols-4 gap-3 border-y border-navy-800 py-4"><div><div className="text-lg font-semibold text-white">{total}</div><div className="text-[10px] text-navy-500">Requests</div></div><div><div className="text-lg font-semibold text-success-400">{approved}</div><div className="text-[10px] text-navy-500">Approved</div></div><div><div className="text-lg font-semibold text-danger-400">{blocked}</div><div className="text-[10px] text-navy-500">Blocked</div></div><div><div className="text-lg font-semibold text-warning-400">{escalated}</div><div className="text-[10px] text-navy-500">Escalated</div></div></div><div className="mt-4 flex items-end justify-between"><div><div className="text-[10px] uppercase tracking-wider text-navy-600">Trust score</div><div className="mt-1 flex items-center gap-2"><span className={`text-xl font-semibold ${agent.trust_score >= 80 ? 'text-success-400' : agent.trust_score >= 60 ? 'text-warning-400' : 'text-danger-400'}`}>{agent.trust_score}</span><div className="h-1.5 w-24 overflow-hidden rounded-full bg-navy-800"><div className={`h-full rounded-full ${agent.trust_score >= 80 ? 'bg-success-500' : agent.trust_score >= 60 ? 'bg-warning-500' : 'bg-danger-500'}`} style={{ width: `${agent.trust_score}%` }} /></div></div></div><div className="text-right"><div className="text-[10px] uppercase tracking-wider text-navy-600">Executed value</div><div className="mt-1 text-sm font-semibold text-white">{compactMoney(totalValue)}</div></div></div><div className="mt-4 flex justify-end"><button className="btn-ghost px-2 py-1 text-xs" onClick={async () => { await updateAgentStatus(agent.id, agent.status === 'active' ? 'suspended' : 'active'); onRefresh(); }}>{agent.status === 'active' ? 'Suspend agent' : 'Activate agent'}</button></div></div>)}</div></>; }

function Simulator({ authorizations, agents, merchants, onComplete }: { authorizations: Authorization[]; agents: Agent[]; merchants: Merchant[]; onComplete: (result: Awaited<ReturnType<typeof simulateTransaction>>) => void }) { const [scenario, setScenario] = useState('A'); const [form, setForm] = useState({ authorization_id: authorizations[0]?.id || '', agent_id: agents[0]?.id || '', merchant_id: merchants[0]?.id || '', amount: '64999', currency: 'INR', quantity: '1', purpose: 'laptop_purchase' }); const [running, setRunning] = useState(false); const [done, setDone] = useState(false); const loadScenario = (id: string) => { const s = DEMO_SCENARIOS.find(x => x.id === id); if (!s) return; setScenario(id); setForm({ ...s.input, amount: String(s.input.amount), quantity: String(s.input.quantity) }); setDone(false); }; const run = async () => { setRunning(true); try { const res = await simulateTransaction({ ...form, amount: Number(form.amount), quantity: Number(form.quantity) }); onComplete(res); setDone(true); } finally { setRunning(false); } }; return <><PageHeader eyebrow="Control plane" title="Transaction simulator" description="Submit a proposed agent payment and watch VeriFlow enforce the user's authorization in real time." action={<div className="flex items-center gap-2 text-xs text-navy-500"><span className="h-2 w-2 rounded-full bg-success-400" />Mock payment mode</div>} /><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><div className="card p-5 sm:p-6"><div className="mb-6 flex items-center justify-between"><div><h2 className="text-sm font-semibold text-white">Agent request</h2><p className="mt-1 text-xs text-navy-500">What the autonomous agent wants to do</p></div><span className="badge-pending"><Bot size={12} />PROPOSED ACTION</span></div><div className="mb-6 grid grid-cols-3 gap-2">{DEMO_SCENARIOS.map(s => <button key={s.id} onClick={() => loadScenario(s.id)} className={`rounded-lg border p-3 text-left transition-colors ${scenario === s.id ? 'border-accent-500/50 bg-accent-500/10' : 'border-navy-800 bg-navy-950 hover:border-navy-700'}`}><div className="flex items-center justify-between"><span className={`flex h-5 w-5 items-center justify-center rounded text-[10px] font-bold ${scenario === s.id ? 'bg-accent-500 text-white' : 'bg-navy-800 text-navy-400'}`}>{s.id}</span>{scenario === s.id && <Check size={13} className="text-accent-400" />}</div><div className="mt-2 text-[11px] font-medium text-navy-200">{s.title}</div></button>)}</div><div className="space-y-4"><div><label className="label">Authorization</label><select className="input" value={form.authorization_id} onChange={e => setForm({ ...form, authorization_id: e.target.value })}>{authorizations.map(a => <option key={a.id} value={a.id}>{shortId(a.id)} · {money(Number(a.max_amount))} max · {a.purpose}</option>)}</select></div><div className="grid gap-4 sm:grid-cols-2"><div><label className="label">Agent identity</label><select className="input" value={form.agent_id} onChange={e => setForm({ ...form, agent_id: e.target.value })}>{agents.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></div><div><label className="label">Merchant</label><select className="input" value={form.merchant_id} onChange={e => setForm({ ...form, merchant_id: e.target.value })}>{merchants.map(m => <option key={m.id} value={m.id}>{m.name} · {m.category}</option>)}</select></div></div><div className="grid gap-4 sm:grid-cols-3"><div><label className="label">Amount</label><div className="relative"><span className="absolute left-3 top-2 text-sm text-navy-500">₹</span><input className="input pl-7" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} /></div></div><div><label className="label">Currency</label><select className="input" value={form.currency} onChange={e => setForm({ ...form, currency: e.target.value })}><option>INR</option><option>USD</option><option>SGD</option></select></div><div><label className="label">Quantity</label><input className="input" type="number" min="1" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} /></div></div><div><label className="label">Payment purpose</label><input className="input" value={form.purpose} onChange={e => setForm({ ...form, purpose: e.target.value })} /></div></div><button className="btn-primary mt-7 w-full py-3" onClick={run} disabled={running}>{running ? <><RefreshCw size={16} className="animate-spin" />Evaluating policy and risk…</> : <><Play size={16} />Evaluate proposed transaction</>}</button>{done && <div className="mt-3 flex items-center justify-center gap-2 text-xs text-success-400"><CheckCircle2 size={14} />Decision recorded with evidence hash</div>}</div><div className="space-y-5"><div className="card border-accent-500/20 bg-accent-500/[.03] p-5"><div className="flex items-center gap-2 text-sm font-semibold text-accent-300"><Sparkles size={16} />What happens next</div><div className="mt-4 space-y-4">{['Load user authorization', 'Run deterministic policy checks', 'Score explainable risk factors', 'Approve, block, or escalate', 'Simulate payment if approved', 'Seal tamper-evident evidence'].map((s, i) => <div key={s} className="flex items-center gap-3"><div className="flex h-6 w-6 items-center justify-center rounded-full border border-accent-500/30 bg-accent-500/10 text-[10px] font-semibold text-accent-300">{i + 1}</div><span className="text-xs text-navy-300">{s}</span>{i < 5 && <ChevronDown size={13} className="ml-auto text-navy-700" />}</div>)}</div></div><div className="card p-5"><div className="flex items-center gap-2 text-xs font-semibold text-navy-200"><LockKeyhole size={14} className="text-success-400" />Safety boundary</div><p className="mt-2 text-xs leading-5 text-navy-500">The risk engine is deterministic and policy-first. AI-style explanations can describe a decision, but never execute a financial action.</p></div></div></div></>; }

function DecisionCenter({ transactions, onOpen }: { transactions: TransactionWithRelations[]; onOpen: (t: TransactionWithRelations) => void }) { const [filter, setFilter] = useState<'all' | 'blocked' | 'escalated' | 'executed'>('all'); const filtered = transactions.filter(t => filter === 'all' ? true : filter === 'executed' ? t.status === 'executed' || t.status === 'approved' : t.status === filter); return <><PageHeader eyebrow="Investigation" title="Risk decision center" description="Review every policy check and risk signal that shaped an autonomous payment decision." action={<div className="flex items-center gap-2"><Filter size={14} className="text-navy-500" /><select className="input w-auto py-1.5 text-xs" value={filter} onChange={e => setFilter(e.target.value as typeof filter)}><option value="all">All decisions</option><option value="blocked">Blocked</option><option value="escalated">Escalated</option><option value="executed">Approved</option></select></div>} /><div className="mb-5 flex gap-2 overflow-x-auto"><div className="badge-blocked"><Ban size={12} />{transactions.filter(t => t.status === 'blocked').length} blocked</div><div className="badge-escalated"><AlertTriangle size={12} />{transactions.filter(t => t.status === 'escalated').length} need review</div><div className="badge-approved"><CheckCircle2 size={12} />{transactions.filter(t => t.status === 'executed').length} approved</div></div><div className="card overflow-hidden"><div className="hidden grid-cols-[1.25fr_1fr_1fr_.7fr_.8fr] gap-4 border-b border-navy-800 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-navy-600 sm:grid"><span>Transaction</span><span>Authorization vs action</span><span>Risk analysis</span><span>Decision</span><span /></div>{filtered.length ? filtered.map(t => <button key={t.id} onClick={() => onOpen(t)} className="grid w-full grid-cols-[1.25fr_1fr_1fr_.7fr_.8fr] items-center gap-4 border-b border-navy-800/70 px-5 py-4 text-left last:border-0 hover:bg-navy-800/35"><div><div className="font-mono text-xs text-accent-300">{shortId(t.id)}</div><div className="mt-1 text-xs font-medium text-navy-200">{t.merchant?.name}</div><div className="mt-1 text-[10px] text-navy-600">{timeAgo(t.created_at)} · {t.agent?.name}</div></div><div><div className="flex items-center gap-2 text-xs"><span className="text-navy-500">Limit</span><span className="font-medium text-navy-200">{money(Number(t.authorization?.max_amount || 0))}</span></div><div className="mt-1 flex items-center gap-2 text-xs"><span className="text-navy-500">Actual</span><span className={`font-semibold ${Number(t.amount) > Number(t.authorization?.max_amount || 0) ? 'text-danger-400' : 'text-success-400'}`}>{money(Number(t.amount))}</span></div></div><div>{t.risk_decision ? <><RiskPill score={t.risk_decision.risk_score} level={t.risk_decision.risk_level} /><div className="mt-2 max-w-[200px] truncate text-[10px] text-navy-500">{t.risk_decision.explanation}</div></> : <span className="text-xs text-navy-600">No analysis</span>}</div><StatusBadge status={t.status} /><div className="flex justify-end text-navy-600"><ChevronRight size={16} /></div></button>) : <EmptyState icon={Gauge} title="No matching decisions" text="Try a different filter or run a new demo scenario." />}</div></>; }

function EvidenceExplorer({ evidence, onOpen, onRefresh }: { evidence: (EvidenceRecord & { transaction?: TransactionWithRelations })[]; onOpen: (tx: TransactionWithRelations) => void; onRefresh: () => void }) { const [query, setQuery] = useState(''); const [verifying, setVerifying] = useState<string | null>(null); const [verifyResult, setVerifyResult] = useState<{ id: string; valid: boolean } | null>(null); const filtered = evidence.filter(e => !query || e.evidence_hash.includes(query) || e.transaction_id.includes(query)); const verify = async (id: string) => { setVerifying(id); const isValid = await verifyEvidence(id); setVerifying(null); setVerifyResult({ id, valid: isValid }); onRefresh(); }; return <><PageHeader eyebrow="Investigation" title="Evidence explorer" description="Reconstruct and verify the immutable-style evidence trail behind every payment decision." action={<button className="btn-secondary" onClick={onRefresh}><RefreshCw size={14} />Refresh chain</button>} /><div className="mb-5 flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search size={15} className="absolute left-3 top-2.5 text-navy-600" /><input className="input pl-9" placeholder="Search evidence hash or transaction…" value={query} onChange={e => setQuery(e.target.value)} /></div><div className="badge-approved"><ShieldCheck size={12} />{evidence.filter(e => e.verified).length}/{evidence.length} verified</div></div><div className="card overflow-hidden"><div className="hidden grid-cols-[1.2fr_1.2fr_.8fr_1fr_.6fr] gap-4 border-b border-navy-800 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-navy-600 sm:grid"><span>Evidence record</span><span>Transaction</span><span>Decision</span><span>Hash chain</span><span /></div>{filtered.length ? filtered.map(e => <div key={e.id} className="grid grid-cols-[1.2fr_1.2fr_.8fr_1fr_.6fr] items-center gap-4 border-b border-navy-800/70 px-5 py-4 last:border-0"><div><div className="flex items-center gap-2"><Hash size={13} className="text-accent-400" /><span className="font-mono text-[11px] text-navy-300">{shortId(e.evidence_hash)}</span></div><div className="mt-1 text-[10px] text-navy-600">Sealed {timeAgo(e.created_at)}</div></div><button className="text-left" onClick={() => e.transaction && onOpen(e.transaction)}><div className="font-mono text-xs text-accent-300">{shortId(e.transaction_id)}</div><div className="mt-1 text-[10px] text-navy-500">{e.transaction?.merchant?.name || 'Transaction record'}</div></button><StatusBadge status={e.transaction?.status} /><div><div className="flex items-center gap-1.5 text-xs text-success-400"><span className="h-1.5 w-1.5 rounded-full bg-success-400" />Verified</div><div className="mt-1 font-mono text-[9px] text-navy-600">prev: {shortId(e.previous_hash)}</div></div><button className="btn-ghost justify-end px-1 text-[11px]" onClick={() => verify(e.id)} disabled={verifying === e.id}>{verifying === e.id ? <RefreshCw size={13} className="animate-spin" /> : <FileCheck2 size={13} />}<span className="hidden xl:inline">Verify</span></button>{verifyResult && verifyResult.id === e.id && <div className={`mt-2 flex items-center gap-1.5 text-[10px] font-medium ${verifyResult.valid ? 'text-success-400' : 'text-danger-400'}`}>{verifyResult.valid ? <><ShieldCheck size={11} />INTEGRITY VERIFIED</> : <><AlertTriangle size={11} />INTEGRITY COMPROMISED</>}</div>}</div>) : <EmptyState icon={FileSearch} title="No evidence records" text="Every evaluated transaction generates a hash-sealed evidence record." />}</div></>; }

function Policies() { const controls = [{ icon: LockKeyhole, title: 'Authorization validity', desc: 'Reject expired or revoked authorizations before any risk scoring.', state: 'Enforced', tone: 'success' }, { icon: CircleDollarSign, title: 'Amount boundaries', desc: 'Compare the proposed amount against the user-granted maximum.', state: 'Enforced', tone: 'success' }, { icon: Target, title: 'Merchant & category scope', desc: 'Validate merchant identity and category against the allow-list.', state: 'Enforced', tone: 'success' }, { icon: History, title: 'Behavioral frequency', desc: 'Escalate unusual transaction bursts and repeated failures.', state: 'Enforced', tone: 'warning' }, { icon: FileCheck2, title: 'Evidence integrity', desc: 'Hash every decision payload and link records in a chain.', state: 'Enforced', tone: 'success' }, { icon: Shield, title: 'Human escalation', desc: 'Route ambiguous risk to reviewer before payment execution.', state: 'Required', tone: 'accent' }]; return <><PageHeader eyebrow="Configuration" title="Policies & controls" description="The guardrails that sit between an autonomous agent's intent and payment execution." /><div className="mb-6 card border-accent-500/20 bg-accent-500/[.03] p-5"><div className="flex items-start gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-accent-500/10 text-accent-400"><ShieldCheck size={20} /></div><div><div className="text-sm font-semibold text-white">Policy-first execution</div><p className="mt-1 max-w-2xl text-xs leading-5 text-navy-400">No AI-generated explanation can override deterministic policy checks. Payment execution only begins after authorization validation and a passing risk decision.</p></div><span className="ml-auto hidden badge-approved sm:inline-flex"><span className="h-1.5 w-1.5 rounded-full bg-current" />Active</span></div></div><div className="grid gap-4 sm:grid-cols-2">{controls.map(c => <div key={c.title} className="card-hover flex gap-4 p-5"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-navy-800 text-accent-400"><c.icon size={17} /></div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><div className="text-sm font-medium text-white">{c.title}</div><span className={`badge-${c.tone === 'warning' ? 'escalated' : c.tone === 'accent' ? 'executed' : 'approved'}`}>{c.state}</span></div><p className="mt-2 text-xs leading-5 text-navy-500">{c.desc}</p></div></div>)}</div></>; }

function SettingsPage() { const [mode, setMode] = useState(true); return <><PageHeader eyebrow="Configuration" title="Settings" description="Manage workspace defaults and the boundaries of this sandbox environment." /><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="card divide-y divide-navy-800"><div className="p-5"><h2 className="text-sm font-semibold text-white">Workspace</h2><p className="mt-1 text-xs text-navy-500">Identity and operational preferences</p></div><div className="space-y-4 p-5"><div><label className="label">Workspace name</label><input className="input" value="VeriFlow Demo Workspace" readOnly /></div><div><label className="label">Default currency</label><select className="input"><option>INR — Indian Rupee</option><option>USD — US Dollar</option></select></div><div><label className="label">Review queue threshold</label><select className="input"><option>Medium risk and above</option><option>High risk only</option></select></div></div></div><div className="space-y-5"><div className="card p-5"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-success-500/10 text-success-400"><Server size={17} /></div><div><div className="text-sm font-medium text-white">Payment provider</div><div className="mt-1 text-xs text-navy-500">Razorpay-style sandbox adapter</div></div></div><div className="mt-5 flex items-center justify-between rounded-lg border border-navy-800 bg-navy-950 p-3"><div className="flex items-center gap-2 text-xs text-navy-300"><span className="h-2 w-2 rounded-full bg-success-400" />Mock mode</div><button className={`relative h-6 w-11 rounded-full transition-colors ${mode ? 'bg-accent-600' : 'bg-navy-700'}`} onClick={() => setMode(!mode)}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-transform ${mode ? 'left-6' : 'left-1'}`} /></button></div><p className="mt-3 text-[11px] leading-5 text-navy-600">No credentials are stored in the browser. Live and test mode integrations require a server-side payment proxy.</p></div><div className="card p-5"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent-500/10 text-accent-400"><Database size={17} /></div><div><div className="text-sm font-medium text-white">Data retention</div><div className="mt-1 text-xs text-navy-500">Evidence records are retained indefinitely</div></div></div><div className="mt-5 flex items-center gap-2 text-xs text-success-400"><CheckCircle2 size={14} />Evidence chain is healthy</div></div></div></div></>; }

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><div className="w-full max-w-lg animate-slide-up rounded-2xl border border-navy-700 bg-navy-900 shadow-2xl"><div className="flex items-center justify-between border-b border-navy-800 px-5 py-4"><h2 className="text-sm font-semibold text-white">{title}</h2><button className="btn-ghost p-1.5" onClick={onClose}><X size={16} /></button></div><div className="p-5">{children}</div></div></div>; }

function TransactionDetails({ tx, onClose, onVerify }: { tx: TransactionWithRelations; onClose: () => void; onVerify: () => void }) {
  const decision = tx.risk_decision;
  const agentIdentityCheck = decision?.failed_checks?.find(c => c.name === 'agent_identity') || decision?.passed_checks?.find(c => c.name === 'agent_identity');
  const timeline = [
    { label: 'Agent identity', icon: agentIdentityCheck?.passed ? CheckCircle2 : Ban, detail: agentIdentityCheck?.message || 'Not checked', tone: agentIdentityCheck?.passed ? 'success' : 'danger' },
    { label: 'Authorization', icon: KeyRound, detail: `${money(Number(tx.authorization?.max_amount || 0))} max · ${tx.authorization?.purpose?.replaceAll('_', ' ')}`, tone: 'accent' },
    { label: 'Agent request', icon: Bot, detail: `${tx.agent?.name} proposed ${money(Number(tx.amount))}`, tone: 'accent' },
    { label: 'Policy validation', icon: FileCheck2, detail: `${decision?.passed_checks?.length || 0} passed · ${decision?.failed_checks?.length || 0} failed`, tone: decision?.failed_checks?.length ? 'warning' : 'success' },
    { label: 'AI risk analysis', icon: Brain, detail: decision?.ai_analysis?.reasoning || 'No AI analysis available', tone: 'accent' },
    { label: 'Decision guard', icon: ShieldCheck, detail: decision?.ai_analysis?.overridden_by_policy ? 'AI recommendation overridden by deterministic policy' : 'Deterministic policy confirmed', tone: 'success' },
    { label: 'Decision', icon: decision?.decision === 'approved' ? CheckCircle2 : decision?.decision === 'blocked' ? Ban : AlertTriangle, detail: decision?.explanation || 'No explanation available', tone: decision?.decision === 'approved' ? 'success' : decision?.decision === 'blocked' ? 'danger' : 'warning' },
    ...(tx.payment_events?.length ? [{ label: 'Payment execution', icon: CreditCard, detail: `${tx.payment_events.length} sandbox events · ${tx.payment_events[tx.payment_events.length - 1]?.status}`, tone: 'success' }] : []),
    { label: 'Evidence sealed', icon: Hash, detail: shortId(tx.evidence?.evidence_hash), tone: 'success' },
  ];
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-navy-950/95 p-4 backdrop-blur-sm sm:p-8">
    <div className="mx-auto max-w-4xl animate-slide-up">
      <div className="mb-5 flex items-center justify-between"><div><div className="mb-2 flex items-center gap-2 text-[11px] font-semibold uppercase tracking-[.18em] text-accent-400"><FileSearch size={13} />Evidence timeline</div><h2 className="text-xl font-semibold text-white">Transaction {shortId(tx.id)}</h2></div><button className="btn-secondary" onClick={onClose}><X size={15} />Close</button></div>
      <div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
        <div className="card p-5 sm:p-6"><div className="mb-6 flex items-start justify-between"><div><div className="text-xs text-navy-500">Lifecycle reconstruction</div><div className="mt-1 text-sm font-medium text-white">Authorization → Evidence</div></div><StatusBadge status={tx.status} /></div>
          <div className="relative ml-2 space-y-0">{timeline.map((item, i) => <div key={item.label} className="relative flex gap-4 pb-7 last:pb-0"><div className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-navy-700 bg-navy-900 text-accent-400"><item.icon size={14} />{i < timeline.length - 1 ? <span className="absolute left-1/2 top-8 h-full w-px -translate-x-1/2 bg-navy-800" /> : null}</div><div className="min-w-0 pt-1"><div className="text-xs font-semibold text-navy-100">{item.label}</div><div className="mt-1 text-xs leading-5 text-navy-500">{item.detail}</div></div></div>)}</div>
        </div>
        <div className="space-y-5">
          <div className="card p-5"><SectionTitle title="Authorization vs actual" /><div className="space-y-3"><div className="flex justify-between text-xs"><span className="text-navy-500">Authorized maximum</span><span className="font-semibold text-navy-200">{money(Number(tx.authorization?.max_amount || 0))}</span></div><div className="flex justify-between text-xs"><span className="text-navy-500">Proposed amount</span><span className={`font-semibold ${Number(tx.amount) > Number(tx.authorization?.max_amount || 0) ? 'text-danger-400' : 'text-success-400'}`}>{money(Number(tx.amount))}</span></div><div className="flex justify-between border-t border-navy-800 pt-3 text-xs"><span className="text-navy-500">Merchant</span><span className="font-medium text-navy-200">{tx.merchant?.name}</span></div><div className="flex justify-between text-xs"><span className="text-navy-500">Category</span><span className="font-medium text-navy-200">{tx.merchant?.category}</span></div></div></div>
          <div className="card p-5"><SectionTitle title="Risk factors" />{decision?.risk_factors?.length ? <div className="space-y-3">{decision.risk_factors.map(f => <div key={f.factor} className="flex gap-2"><AlertTriangle size={13} className="mt-0.5 shrink-0 text-warning-400" /><div><div className="text-xs font-medium text-navy-200">{f.label}</div><div className="mt-0.5 text-[11px] leading-4 text-navy-500">{f.detail}</div></div></div>)}</div> : <div className="flex items-center gap-2 text-xs text-success-400"><CheckCircle2 size={14} />No risk factors triggered</div>}</div>
          {decision?.ai_analysis && <div className="card p-5"><div className="flex items-center gap-2 text-xs font-semibold text-navy-200"><Brain size={14} className="text-accent-400" />AI Risk Reasoner</div><div className="mt-3 space-y-3"><div className="flex items-center justify-between text-xs"><span className="text-navy-500">Recommendation</span><span className={`font-semibold ${decision.ai_analysis.recommendation === 'approved' ? 'text-success-400' : decision.ai_analysis.recommendation === 'blocked' ? 'text-danger-400' : 'text-warning-400'}`}>{decision.ai_analysis.recommendation.toUpperCase()}</span></div><div className="flex items-center justify-between text-xs"><span className="text-navy-500">Confidence</span><span className="font-mono text-navy-200">{decision.ai_analysis.confidence}%</span></div>{decision.ai_analysis.overridden_by_policy && <div className="flex items-center gap-1.5 rounded-lg border border-danger-500/20 bg-danger-500/5 p-2 text-[11px] text-danger-400"><Shield size={12} />Overridden by deterministic policy</div>}<div className="rounded-lg bg-navy-950 p-3"><div className="text-[11px] leading-5 text-navy-300">{decision.ai_analysis.reasoning}</div></div>{decision.ai_analysis.risk_signals.length > 0 && <div><div className="mb-1.5 text-[10px] uppercase tracking-wider text-navy-600">Risk signals</div><div className="space-y-1">{decision.ai_analysis.risk_signals.map((s, i) => <div key={i} className="flex gap-1.5 text-[11px] leading-4 text-navy-400"><span className="text-warning-400">•</span>{s}</div>)}</div></div>}</div></div>}
          <div className="card p-5"><div className="flex items-center gap-2 text-xs font-semibold text-navy-200"><Hash size={14} className="text-accent-400" />Evidence integrity</div><div className="mt-3 rounded-lg bg-navy-950 p-3"><div className="break-all font-mono text-[10px] leading-5 text-accent-300">{tx.evidence?.evidence_hash || 'Hash unavailable'}</div></div><div className="mt-3 flex items-center justify-between"><span className="flex items-center gap-1.5 text-xs text-success-400"><ShieldCheck size={13} />{tx.evidence?.verified ? 'Verified intact' : 'Needs verification'}</span>{tx.evidence ? <button className="btn-ghost px-2 py-1 text-[11px]" onClick={onVerify}><FileCheck2 size={13} />Verify now</button> : null}</div></div>
        </div>
      </div>
    </div>
  </div>;
}

export default function App() {
  const [page, setPage] = useState<Page>('dashboard');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState<Awaited<ReturnType<typeof getDashboardStats>> | null>(null);
  const [trend, setTrend] = useState<Awaited<ReturnType<typeof getRiskTrend>>>([]);
  const [transactions, setTransactions] = useState<TransactionWithRelations[]>([]);
  const [authorizations, setAuthorizations] = useState<(Authorization & { agent?: Agent })[]>([]);
  const [agents, setAgents] = useState<Agent[]>([]);
  const [merchants, setMerchants] = useState<Merchant[]>([]);
  const [activity, setActivity] = useState<Awaited<ReturnType<typeof getAgentActivity>>>([]);
  const [evidence, setEvidence] = useState<(EvidenceRecord & { transaction?: TransactionWithRelations })[]>([]);
  const [selectedTx, setSelectedTx] = useState<TransactionWithRelations | null>(null);
  const [demoRunning, setDemoRunning] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const refresh = async () => { const [s, tr, tx, au, ag, me, ac, ev] = await Promise.all([getDashboardStats(), getRiskTrend(), getRecentTransactions(12), getAllAuthorizations(), getAllAgents(), getAllMerchants(), getAgentActivity(), getAllEvidence()]); setStats(s); setTrend(tr); setTransactions(tx); setAuthorizations(au); setAgents(ag); setMerchants(me); setActivity(ac); setEvidence(ev as (EvidenceRecord & { transaction?: TransactionWithRelations })[]); };
  useEffect(() => { (async () => { try { await seedDatabase(); await refresh(); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load workspace'); } finally { setLoading(false); } })(); }, []);
  const openTx = async (tx: TransactionWithRelations) => { const fresh = await getTransactionById(tx.id); setSelectedTx(fresh || tx); };
  const runDemo = async (scenarioId: string = 'A') => { setDemoRunning(true); try { const result = await runDemoScenario(scenarioId); await refresh(); setSelectedTx(result.transaction); setToast(scenarioId === 'D' ? 'Agent compromise blocked — evidence sealed' : 'Agentic payment approved and evidence sealed'); } catch (e) { setToast(e instanceof Error ? e.message : 'Demo failed'); } finally { setDemoRunning(false); setTimeout(() => setToast(null), 4000); } };
  const handleSimulation = async (result: Awaited<ReturnType<typeof simulateTransaction>>) => { await refresh(); setSelectedTx(result.transaction); };
  if (loading) return <div className="flex min-h-screen items-center justify-center bg-navy-950"><div className="text-center"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-accent-600 shadow-lg shadow-accent-600/20"><ShieldCheck className="text-white" /></div><div className="mt-5 text-sm font-medium text-white">Initializing VeriFlow</div><div className="mt-2 text-xs text-navy-500">Loading trust workspace and evidence chain…</div><div className="mx-auto mt-5 h-1 w-32 overflow-hidden rounded-full bg-navy-800"><div className="h-full w-1/2 animate-shimmer rounded-full bg-accent-500" /></div></div></div>;
  if (error) return <div className="flex min-h-screen items-center justify-center bg-navy-950 p-6"><div className="card max-w-md p-6 text-center"><AlertTriangle className="mx-auto text-warning-400" /><h2 className="mt-3 text-sm font-semibold text-white">Workspace unavailable</h2><p className="mt-2 text-xs leading-5 text-navy-500">{error}</p><button className="btn-primary mt-5" onClick={() => window.location.reload()}><RefreshCw size={14} />Retry</button></div></div>;
  const content = page === 'dashboard' ? <Dashboard stats={stats} trend={trend} transactions={transactions} onOpen={openTx} setPage={setPage} /> : page === 'authorizations' ? <Authorizations authorizations={authorizations} agents={agents} onRefresh={async () => { setAuthorizations(await getAllAuthorizations()); }} /> : page === 'agents' ? <Agents activity={activity} onRefresh={async () => setActivity(await getAgentActivity())} /> : page === 'simulator' ? <Simulator authorizations={authorizations} agents={agents} merchants={merchants} onComplete={handleSimulation} /> : page === 'decisions' ? <DecisionCenter transactions={transactions} onOpen={openTx} /> : page === 'evidence' ? <EvidenceExplorer evidence={evidence} onOpen={openTx} onRefresh={async () => setEvidence(await getAllEvidence() as (EvidenceRecord & { transaction?: TransactionWithRelations })[])} /> : page === 'policies' ? <Policies /> : <SettingsPage />;
  return <><Shell page={page} setPage={setPage} onDemo={runDemo}>{content}</Shell>{selectedTx && <TransactionDetails tx={selectedTx} onClose={() => setSelectedTx(null)} onVerify={async () => { if (selectedTx.evidence) { await verifyEvidence(selectedTx.evidence.id); const fresh = await getTransactionById(selectedTx.id); setSelectedTx(fresh); await refresh(); } }} />}{demoRunning && <div className="fixed bottom-5 right-5 z-50 flex items-center gap-3 rounded-xl border border-accent-500/30 bg-navy-900 px-4 py-3 shadow-2xl"><RefreshCw size={15} className="animate-spin text-accent-400" /><span className="text-xs text-navy-200">Running agentic payment demo…</span></div>}{toast && <div className="fixed bottom-5 right-5 z-50 flex items-center gap-3 rounded-xl border border-success-500/30 bg-navy-900 px-4 py-3 shadow-2xl"><CheckCircle2 size={15} className="text-success-400" /><span className="text-xs text-navy-200">{toast}</span></div>}</>;
}
